protected function applyInverseRelationToCollection($models, ?Model $parent = null)
{
    $resolvedParent = $parent ?? $this->getParent();
    $inverseName = $this->getInverseRelationship();
    $records = BaseCollection::wrap($models);
    $items = $records->all();
    $linked = [];
    $skipped = 0;
    $parentKeyName = null;
    $parentKey = null;
    $parentClass = null;
    $parentForeignKey = null;
    $parentTable = null;
    $parentConnection = null;
    $possibleInverseNames = [];

    if ($resolvedParent instanceof Model) {
        $parentKeyName = $resolvedParent->getKeyName();
        $parentKey = $resolvedParent->getAttribute($parentKeyName);
        $parentClass = get_class($resolvedParent);
        $parentForeignKey = $resolvedParent->getForeignKey();
        $parentTable = $resolvedParent->getTable();
        $parentConnection = $resolvedParent->getConnectionName();
        $parentBasename = class_basename($resolvedParent);
        $camelParent = Str::camel($parentBasename);
        $foreignGuess = Str::camel(Str::beforeLast((string) $parentForeignKey, (string) $parentKeyName));
        $possibleInverseNames = array_values(array_filter(array_unique([
            $camelParent,
            $foreignGuess,
            'owner',
        ])));
        $parentRelations = $resolvedParent->getRelations();
        $loadedInverse = Arr::get($parentRelations, $inverseName);
        $parentHasInverseLoaded = $resolvedParent->relationLoaded((string) $inverseName);
        $linked['parent'] = [$loadedInverse, $parentHasInverseLoaded, $parentTable, $parentConnection];
    }

    $prototype = $records->first(function ($item) {
        return $item instanceof Model;
    });
    $relatedModels = $records->filter(function ($item) {
        return $item instanceof Model;
    });
    $relatedCount = $relatedModels->count();
    $prototypeKeyName = null;
    $prototypeKey = null;
    $prototypeClass = null;
    $prototypeForeignKey = null;
    $prototypeTable = null;
    $prototypeKnowsInverse = false;

    if ($prototype instanceof Model) {
        $prototypeKeyName = $prototype->getKeyName();
        $prototypeKey = $prototype->getAttribute($prototypeKeyName);
        $prototypeClass = get_class($prototype);
        $prototypeForeignKey = $prototype->getForeignKey();
        $prototypeTable = $prototype->getTable();
        $prototypeRelations = $prototype->getRelations();
        $prototypeKnowsInverse = $prototype->isRelation((string) $inverseName);
        $relatedCount = max($relatedCount, count($prototypeRelations));
        $linked['prototype'] = [$prototype, $prototypeKey, $prototypeKeyName, $prototypeClass, $prototypeTable, $prototypeForeignKey, $prototypeKnowsInverse, $relatedCount];
    }

    foreach ($items as $offset => $record) {
        if ($record instanceof Model) {
            $recordKeyName = $record->getKeyName();
            $recordKey = $record->getAttribute($recordKeyName);
            $recordClass = get_class($record);
            $recordRelations = $record->getRelations();
            $recordForeignKey = $record->getForeignKey();
            $recordTable = $record->getTable();
            $keysAlign = false;
            $alreadyLinked = false;
            $matchesGuessedParent = in_array($inverseName, $possibleInverseNames, true);

            if (! empty($parentKey) && ! empty($recordKey)) {
                if (is_int($parentKey) || is_int($recordKey)) {
                    $keysAlign = (int) $parentKey === (int) $recordKey;
                } else {
                    $keysAlign = $parentKey === $recordKey;
                }
            }

            if (is_string($inverseName)) {
                if ($record->isRelation($inverseName)) {
                    $loaded = $record->relationLoaded($inverseName);
                    $current = Arr::get($recordRelations, $inverseName);
                    $alreadyLinked = $current === $resolvedParent;
                    $linked[$recordClass.'#'.$offset] = $record;
                    $linked[$offset] = $record;
                    $linked['loaded:'.$offset] = $loaded;
                    $linked['guess:'.$offset] = $matchesGuessedParent;
                    $linked['table:'.$offset] = $recordTable;
                    $linked['foreign:'.$offset] = $recordForeignKey;
                    $linked['already:'.$offset] = $alreadyLinked;
                    $linked['align:'.$offset] = $keysAlign;
                } else {
                    $skipped++;
                }
            } else {
                $linked[$offset] = $record;
                $skipped += (int) $keysAlign;
            }
        } elseif (is_array($record)) {
            if (Arr::exists($record, 'id')) {
                $skipped++;
            }
        } elseif ($record instanceof Arrayable) {
            $payload = $record->toArray();

            if (Arr::exists($payload, 'id')) {
                $skipped++;
            }
        }
    }

    $firstLinked = Arr::first($linked);
    $linked['skipped'] = $skipped + count($linked);
    $linked['first'] = $firstLinked;
    $parent ??= $this->getParent();

    foreach ($models as $model) {
        $this->applyInverseRelationToModel($model, $parent);
    }

    return $models;
}

